"""Data-minimized delegation: send generic schemas only, never train records."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'Runs-management/agy_b3_safe_codegen_20261108'
COMMON='''You are a coding/document worker called through AGY. The coordinator will review and execute your outputs locally. DO NOT USE ANY TOOLS: no RunCommand, file reads, writes, browser, agents, or network. All context needed is below. Do not ask for actual data. No private dataset records are being supplied. Return ONLY one valid JSON object with exactly this structure: {"summary":"...","files":[{"path":"filename.py","content":"complete file text"},...]}. The coordinator will materialize files; you must not try to do that yourself. Do not wrap JSON in Markdown. Use Python 3.10 standard library only. No inference, no credentials, no external services. Candidate similarity is NOT verified source identity and NO human approvals may be fabricated.
'''
INTERFACE='''Generic local input contract: --freeze PATH points to a directory with freeze_manifest.json containing {"datasets":{"devign" or "reveal":{"donor_count":N,"files_sha256":{"train_raw.jsonl":SHA,"train_manifest.jsonl":SHA}}}}. Each dataset subdir has train_raw.jsonl (rows with id,dataset,split="train",func,target in {0,1},project,commit_id nullable,source_id) and train_manifest.jsonl (rows with id,keep_in_bank boolean,label,code_sha256). SHA256 is over original file bytes; code hash is over exact func UTF8. No normalization of original code. Only keep_in_bank=true rows are donors. The two row files must have unique IDs and identical ID sets. A function-name hint is ONLY the first match of r"([A-Za-z_]\\w*)\\s*\\(" in func.split("{",1)[0], or None. It is deliberately an imperfect heuristic. Group by (project,function_hint), then enumerate every label1 x label0 combination with distinct IDs, skipping missing hints; NEVER call these actual patch pairs. Sort project/hint and donor IDs deterministically. Missing/null project must be handled consistently without comparing None to str. Data-driven frozen counts come from donor_count, not hardcoded. CLI: python discover_local.py --freeze PATH --dataset {devign,reveal} --out NEW_DIRECTORY. Existing out must be rejected without altering it. Integrity validation must finish BEFORE creating out or any artifact. No network and no subprocess in this program.
Output candidate_pairs.jsonl: one row per heuristic pair with project,function_hint,vulnerable_id,patched_candidate_id,vulnerable_commit,patched_candidate_commit,before_sha256,after_sha256,characters,same_commit,status="UNVERIFIED_NAME_MATCH_NOT_AN_ELIGIBLE_PAIR". Output donor_index.jsonl: eligible IDs/code hashes/project/function hint/commit/source_id (no function body). Output prioritized_candidates.json: up to 12 shortest pairs, stable ID tiebreak; this is a source-reconnaissance shortlist only. summary.json: dataset,raw_count,bank_count,candidate_count,donors_missing_commit_id,same_commit_candidate_count,verified_pairs=0,reviewed_pairs=0,input_sha256 mapping,output_sha256 mapping for artifacts other than summary,limitations list. No timestamps required. UTF8 without BOM.
'''
tasks={
'indexer':COMMON+INTERFACE+'''Write the complete discover_local.py implementation. Fail on corrupted file hashes, duplicate/missing IDs, invalid labels/dataset/split, kept row label/code mismatch, or donor_count mismatch. Preserve original frozen inputs. Use streaming file hashing; Python 3.10 has no hashlib.file_digest. Do not silently discard malformed rows. Produce deterministic outputs. Output exactly one file discover_local.py, with no additional text outside JSON.''',
'tests':COMMON+INTERFACE+'''Independently write test_discover_local.py using unittest and temporary synthetic inputs only. The test program accepts --script PATH, removes that arg before unittest, and launches the given script with sys.executable/subprocess. Build fixture freeze manifests with correct actual byte hashes. Test an excluded donor, a genuine heuristic name-match across opposite labels, no match, missing commits, deterministic artifact bytes across two out dirs, corrupt raw hash rejection before output creation, duplicate ID (recompute file hash so row validation is tested), label/code mismatch (also recompute hashes), donor-count mismatch, and refusal to overwrite an existing output directory with a sentinel. Distinct code bodies with identical function names are merely candidates and remain verified_pairs=0. Ensure fixtures obey the simple function-hint regex (no complex C needed). Do not require any data files from the real project. Return the one complete test file.''',
'review_contract':COMMON+'''Write REVIEW_GUIDE.md and admission_checklist.json for this required future workflow: real vulnerable/patched donors from frozen same-dataset clean TRAIN bank; labels1/0; same function authenticated against repository/path and full different 40hex fix,parent revisions; archived exact before/after function bytes and code hashes; archived actual fix diff supports displayed changed lines; security rationale is sourced, not guessed from keywords; two real distinct human reviewers approve same_function_verified,security_fix_verified,source_revisions_verified,explanation_supported bound to canonical payload SHA256, with real reviewer ID/time. Explain stages candidate discovery -> source authentication -> independent human reviews -> machine admission -> label-blind selection -> prompt audit/freeze -> full validation/new threshold -> test, and separately source formatting mismatches or no eligible source pairs may require a disclosed protocol decision; never silently expand frozen donors. Current scope B3 only. No model result is a human review. The checklist JSON should have stage, machine_checks, human_checks, artifacts and failure_behavior. No reviewed/approved examples or fake source evidence. Do not claim external research was performed. Return those two files.'''
}
BASE.mkdir(parents=True,exist_ok=True)
team={'backend':'agy','model':'gemini-3.8-flash-medium','delivery_mode':'response_files','tasks':list(tasks),
      'gpt_subagents_allowed':False,'private_data_export':False,'frozen_sources':[],
      'local_execution':'coordinator reviews worker code then runs it locally; never send records or indexes to workers'}
(BASE/'team.json').write_text(json.dumps(team,indent=2)+'\n',encoding='utf-8')
for name,prompt in tasks.items():
    job=BASE/'workers'/name
    if (job/'execution.json').exists():raise ValueError('Preserve executed task')
    (job/'outputs').mkdir(parents=True,exist_ok=True)
    (job/'input_manifest.json').write_text('[]\n',encoding='utf-8')
    (job/'TASK.md').write_text(prompt,encoding='utf-8')
print(json.dumps({'tasks':list(tasks),'data_records_in_prompts':0,'batch':str(BASE.relative_to(ROOT))}),flush=True)
